local config = {
  ui_story_31290401_1_dialog_content = "¡Estamos aquí!",
  ui_story_31290401_2_dialog_content = "Un mercado, ¿eh? ¡Se ve muy animado!",
  ui_story_31290401_3_dialog_content = "¡Es correcto! ¡Hoy es el <color=#FFB400>día del trueque</color> para los merc. de la llama blanca!",
  ui_story_31290401_4_dialog_content = "<color=#FFB400>¿Día de trueque?</color>",
  ui_story_31290401_5_dialog_content = "En pocas palabras, la gente puede venir aquí a <color=#FFB400>intercambiar sus bienes por otros.</color>",
  ui_story_31290401_6_dialog_content = "Aquí, el valor de los bienes está determinado por las personas que participan, no por su precio en Nightium.",
  ui_story_31290401_7_dialog_content = "¡Un cuadro de flores puede tener el mismo valor que una moneda de cobre de una civilización desaparecida en este mercado!",
  ui_story_31290401_8_dialog_content = "¡Siempre que la persona con la que hagas el trueque esté dispuesta a cambiarla, serás más que bienvenido a hacer una oferta!",
  ui_story_31290401_9_dialog_content = "¡Suena muy bien!",
  ui_story_31290401_10_dialog_content = "Pero... ¿No existe el riesgo de que personas poco escrupulosas vendan productos baratos a cambio de cosas mucho más valiosas?",
  ui_story_31290401_11_dialog_content = "De nuevo, mientras el propietario de un determinado bien esté dispuesto a realizar el intercambio, no hay otras reglas que considerar.",
  ui_story_31290401_12_dialog_content = "A menos, claro, que esa persona intente sacar un beneficio.",
  ui_story_31290401_13_dialog_content = "“Obtener un beneficio\"... ¿Te refieres a comerciar por algo aquí, y luego venderlo por Nightium fuera del mercado?",
  ui_story_31290401_14_dialog_content = "Precisamente. Cuando el entra dinero en la ecuación, el significado del Día del Trueque cambia por completo.",
  ui_story_31290401_15_dialog_content = "¿Pero no sería eso inevitable?",
  ui_story_31290401_16_dialog_content = "Lo es, pero cualquiera que lo haga dejará de ser miembro de los Mercenarios de Llama Blanca, y ya no será bienvenido aquí en Umbraton.",
  ui_story_31290401_17_dialog_content = "Serán objetivo de los mercenarios, hasta que finalmente decidan abandonar la ciudad.",
  ui_story_31290401_18_dialog_content = "(Esto definitivamente suena como... El tipo de cosa que haría una banda de mercenarios...)",
  ui_story_31290401_19_dialog_content = "¿Ves al tipo de allí? Es un buen pintor. He intercambiado mi trabajo con él antes.",
  ui_story_31290401_20_dialog_content = "¡Comandante Luke! ¡Comandante Luke! ¡Llegó una nueva asignación para ti!",
  ui_story_31290401_21_dialog_content = "Lo siento, PlayerName. Parece que tengo algunos asuntos que atender allí.",
  ui_story_31290401_22_dialog_content = "¿Estarás bien solo? ¿Debo enviar a alguien para que se quede contigo?",
  ui_story_31290401_23_dialog_content = "¿Eh? E-Eso no será necesario. Estaré bien por mi cuenta, ¡no te preocupes por mí!",
  ui_story_31290401_24_dialog_content = "Muy bien, entonces tómate tu tiempo y echa un buen vistazo. Vendré a buscarte una vez que haya terminado con esto.",
  ui_story_31290401_25_dialog_content = "¿Una nueva tarea, incluso en el Día del Trueque? Luke está muy ocupado... Supongo que echaré un vistazo por el momento.",
  ui_story_31290401_26_dialog_content = "¡Este mercado es realmente animado! Hay carros de aperitivos, puestos de pintura a mano, e incluso boutiques de joyas...",
  ui_story_31290401_27_dialog_content = "¡Incluso hay alguien que vende mariposas!",
  ui_story_31290401_28_dialog_content = "(¡Eh! ¡Esa es la persona!)",
  ui_story_31290401_29_dialog_content = "(El Comandante Luke se mantenía acompañado personalmente... ¡Estoy seguro de que funcionará!)",
  ui_story_31290401_30_dialog_content = "¡Eh, tú! ¡Sí, tú, el de la diadema blanca y negra!",
  ui_story_31290401_31_dialog_content = "... ¿Ninguna reacción? Tal vez debería acercarme un poco más...",
  ui_story_31290401_32_dialog_content = "<size=45>¡¡Oye tú, con la diadema en blanco y negro !!</size>",
  ui_story_31290401_33_dialog_content = "¡Rayos, el ruido de la multitud debió opacar mi voz! Creo que tendré que... ¡intentar esto!",
  ui_story_31290401_34_dialog_content = "<size=50>¡¡¡Ay!!!</size>",
  ui_story_31290401_35_dialog_content = "<size=50>¡¡¡Mi trasero!!!</size>",
  ui_story_31290401_36_dialog_content = "¡¿Quién fue?! ¡¿Quién me pegó en el trasero?!",
  ui_story_31290401_37_dialog_content = "(... ¿Eh? ¿Me está saludando esa persona?)",
  ui_story_31290401_38_dialog_content = "(Parece que me está pidiendo que vaya para allá... ¡¿Ha visto quién me ha emboscado ahora?!)",
  ui_story_31290401_39_dialog_content = "¡Hola! Uh... ¿Me estabas saludando?",
  ui_story_31290401_40_dialog_content = "¡Así es! Lo siento, amigo... Fui yo quien te lanzó una piedra hace un momento.",
  ui_story_31290401_41_dialog_content = "Pero no había otra opción... ¡lo sabes!",
  ui_story_31290401_42_dialog_content = "Intenté gritarte una y otra vez, pero no parecías escucharme... ¡Y me vendría muy bien tu ayuda!",
  ui_story_31290401_43_dialog_content = "Oh... Espera un segundo, ¿me conoces?",
  ui_story_31290401_44_dialog_content = "¿Y en qué necesitas ayuda, exactamente?",
  ui_story_31290401_45_dialog_content = "Además, ¡¿no tienes otra forma de pedir ayuda que no sea tirando piedras?!",
  ui_story_31290401_46_dialog_content = "... Todavía te duele, ¿eh? Lo siento mucho... ¿Quieres que te lo frote?",
  ui_story_31290401_47_dialog_content = "¡¿Frotarlo?! ¡Sólo dime lo que quieres!",
  ui_story_31290401_48_dialog_content = "Oh, eh... Está bien. ¡Te compensaré una vez que me explique!",
  ui_story_31290401_49_dialog_content = "Verás, te vi aparecer con el Comandante Luke justo ahora... Deben ser muy amigos, ¿verdad?",
  ui_story_31290401_50_dialog_content = "Luke es mi amigo, sí.",
  ui_story_31290401_51_dialog_content = "¿Esto tiene algo que ver con él?",
  ui_story_31290401_52_dialog_content = "¡Lo tiene!",
  ui_story_31290401_53_dialog_content = "El Comandante Luke ha estado demasiado dedicado a su trabajo últimamente.",
  ui_story_31290401_54_dialog_content = "No, dedicado no es la palabra para eso... Obsesionado o poseído es más bien.",
  ui_story_31290401_55_dialog_content = "Se ha vuelto absolutamente loco por su trabajo... ¡Especialmente hoy!",
  ui_story_31290401_56_dialog_content = "¿Hoy? ¿Por qué?",
  ui_story_31290401_57_dialog_content = "Es porque...",
  ui_story_31290401_58_dialog_content = "Bueno, déjame preguntarte, ¿sabes quién era el viejo comandante?",
  ui_story_31290401_59_option_content = "Sí, lo sé.",
  ui_story_31290401_60_dialog_content = "El antiguo comandante era el padre adoptivo de Luke, y el anterior líder de los Mercenarios de Llama Blanca.",
  ui_story_31290401_61_dialog_content = "¡Je, parece que son más cercanos de lo que pensé al principio!",
  ui_story_31290401_62_option_content = "La verdad no...",
  ui_story_31290401_63_dialog_content = "El viejo comandante era el padre adoptivo de Luke, así como el anterior líder de los Mercenarios de Llama Blanca.",
  ui_story_31290401_64_dialog_content = "Después de su muerte, Luke tomó el mando de los Mercenarios de Llama Blanca.",
  ui_story_31290401_65_dialog_content = "Estaban muy unidos.",
  ui_story_31290401_66_dialog_content = "Entiendo...",
  ui_story_31290401_67_dialog_content = "Y como al Comandante Luke siempre le han gustado los insectos, en los anteriores Días del Trueque siempre había muchas muestras de insectos, incluso invernaderos.",
  ui_story_31290401_68_dialog_content = "¡También había breves charlas sobre insectos, en las que el comandante Luke compartía sus conocimientos con todos!",
  ui_story_31290401_69_dialog_content = "Al viejo comandante le encantaba asistir a sus conferencias, aunque no entendiera ni una palabra.",
  ui_story_31290401_70_dialog_content = "¿Invernaderos... para insectos? ¿Necesitan un alojamiento especial o algo así?",
  ui_story_31290401_71_dialog_content = "Pero acabo de ver unas mariposas... No están en ningún tipo de recinto.",
  ui_story_31290401_72_dialog_content = "Podría ser...",
  ui_story_31290401_73_dialog_content = "¡¿Todo este mercado está completamente climatizado?!",
  ui_story_31290401_74_dialog_content = "¡N-No, nada de eso! Acabamos de <color=#FFB400>cambiar la fecha</color> del día del trueque, eso es todo.",
  ui_story_31290401_75_dialog_content = "¿Cambiar la fecha? ... Supongo que tiene sentido.",
  ui_story_31290401_76_dialog_content = "El Día del Trueque no era este día.",
  ui_story_31290401_77_dialog_content = "El cambio fue idea del antiguo comandante.",
  ui_story_31290401_78_dialog_content = "Después del incidente del ‘88, el viejo comandante casi no salía de su lecho.",
  ui_story_31290401_79_dialog_content = "Hace dos años, su enfermedad empeoró repentinamente...",
  ui_story_31290401_80_dialog_content = "Después de eso, más o menos se dio cuenta de que no le quedaba mucho tiempo.",
  ui_story_31290401_81_dialog_content = "Fue entonces cuando le dijo al Teniente del Comandante Luke...",
  ui_story_31290401_82_dialog_content = "Que cambiara la fecha del Día del Trueque de los Mercenarios de Llama Blanca por el de su muerte.",
  ui_story_31290401_83_dialog_content = "Alto... ¿Quieres decir que hoy es en realidad... el <color=#FFB400>día de la muerte</color> del viejo comandante?",
  ui_story_31290401_84_dialog_content = "¿Pero por qué?",
  ui_story_31290401_85_dialog_content = "Mira alrededor...",
  ui_story_31290401_86_dialog_content = "El Día del Trueque se ve muy animado, y todo el mundo parece muy ocupado.",
  ui_story_31290401_87_dialog_content = "Así es. Todos, desde los más altos cargos hasta los más bajos, está más ocupados en el Día del Trueque.",
  ui_story_31290401_88_dialog_content = "Preparando el lugar, realizando inspecciones y controlando el flujo de mercancías durante todo el evento...",
  ui_story_31290401_89_dialog_content = "¡Incluso invitamos a oradores de la Pandilla Istvan para que nos compartan algunas habilidades de gestión!",
  ui_story_31290401_90_dialog_content = "Verá, si todos nos mantenemos ocupados así todo el día ...",
  ui_story_31290401_91_dialog_content = "No tendremos tiempo de extrañar a nuestros amigos muertos.",
  ui_story_31290401_92_dialog_content = "El viejo comandante... Supongo que no quería que ninguno de ustedes pasara este día en silencio o de luto.",
  ui_story_31290401_93_dialog_content = "Eso es correcto.",
  ui_story_31290401_94_dialog_content = "Para honrar sus deseos, nos mantenemos lo más ocupados posible para evitar que el dolor se apodere de nosotros...",
  ui_story_31290401_95_dialog_content = "Pero aún así, el Comandante Luke va a trabajar hasta morir, al ritmo que va.",
  ui_story_31290401_96_dialog_content = "Su trabajo ya le quita tiempo para comer y dormir.",
  ui_story_31290401_97_dialog_content = "Ha estado tosiendo últimamente, y no come tanto como antes...",
  ui_story_31290401_98_dialog_content = "Siempre dice cosas como \"Parece que tengo otro trabajo\" o \"Es hora de salir a la calle a buscar más información...”",
  ui_story_31290401_99_dialog_content = "Hoy no es diferente, a pesar de que le ayudamos a terminar de preparar el Día del Trueque hace mucho tiempo.",
  ui_story_31290401_100_dialog_content = "Aun sabiendo eso, no se ha relajado ni un segundo, y ha salido corriendo a buscar más trabajos.",
  ui_story_31290401_101_dialog_content = "Nos preocupa... Que todavía esté afligido por el antiguo comandante.",
  ui_story_31290401_102_dialog_content = "A tal punto que relajarse o incluso descansar sería un crimen para él.",
  ui_story_31290401_103_dialog_content = "Entiendo.",
  ui_story_31290401_104_dialog_content = "Así que esto debe ser...",
  ui_story_31290401_105_dialog_content = "¿La razón por la que te pido ayuda? La tienes, amigo.",
  ui_story_31290401_106_dialog_content = "Apreciaríamos mucho si pudieras ayudar a nuestro comandante a relajarse un poco. Sacrificar su salud por su trabajo no nos parece bien.",
  ui_story_31290401_107_dialog_content = "Estamos más preocupados por su bienestar que por ver a los Mercenarios de Llama Blanca hacer algo mejor en el mundo.",
  ui_story_31290401_108_dialog_content = "Pero cada vez que le decimos que se relaje, lo único que dice es: \"Lo sé, lo sé...\"",
  ui_story_31290401_109_dialog_content = "Y sigue con sus asuntos como siempre... Podría ser que todavía está de luto, después de todo.",
  ui_story_31290401_110_dialog_content = "*Suspira* Sé que realmente se preocupa por todos nosotros, pero se niega a escuchar cuando sacamos el tema.",
  ui_story_31290401_111_dialog_content = "Ya perdimos un comandante, después de todo...",
  ui_story_31290401_112_dialog_content = "Tienes mi palabra, haré lo posible para ayudar.",
  ui_story_31290401_113_dialog_content = "Yo... no puedo garantizar que nada cambie, para ser honesto...",
  ui_story_31290401_114_dialog_content = "¡Pero eso no me impedirá hacer todo lo que pueda!",
  ui_story_31290401_115_dialog_content = "Yo... ¡No puedo agradecerte suficiente por esto!",
  ui_story_31290401_116_dialog_content = "¿Eh? ¿No es ese de ahí? ¡Parece que finalmente ha vuelto!",
  ui_story_31290401_117_dialog_content = "¿Ya ha terminado con ese trabajo?",
  ui_story_31290401_118_dialog_content = "¡Es él! ¡Entonces te dejaré hacerlo! ¡No vamos a estorbar ni nada!",
  ui_story_31290401_X118_dialog_content = "¡Aún tengo que ir a buscar la piedra que tiré antes!",
  ui_story_31290401_X119_dialog_content = "¡¡No vuelvas hablar de eso!!",
  ui_story_31290401_119_dialog_content = "Ehehe... Lo siento. Haz lo que puedas, amiguito. ¡Contamos contigo!",
  ui_story_31290401_120_dialog_content = "El... Realmente no perdió tiempo en irse...",
  ui_story_31290401_121_dialog_content = "Lo siento mucho, PlayerName. El trabajo surgió en el último momento, pero ya está solucionado.",
  ui_story_31290401_122_dialog_content = "Te vi hablando con uno de mis capitanes hace un momento. ¿Pudo contarte más sobre los Mercenarios de Llama Blanca?",
  ui_story_31290401_123_dialog_content = "Sí... Me dio un relato muy detallado de ustedes y de su historia.",
  ui_story_31290401_124_dialog_content = "Eso es bueno para...",
  ui_story_31290401_125_dialog_content = "Luke... ¿Todavía estás afligido por la muerte del viejo comandante?",
  ui_story_31290401_126_dialog_content = "¿Eh...? ¿El viejo comandante?",
  ui_story_31290401_X126_dialog_content = "... Ya veo. Realmente te dio un relato detallado de nuestra historia.",
  ui_story_31290401_127_dialog_content = "PlayerName...",
  ui_story_31290401_128_dialog_content = "Mentiría si dijera que no me duele todavía la pérdida.",
  ui_story_31290401_129_dialog_content = "Pero creo que lo he asumido de la misma manera que él esperaba que lo hiciera.",
  ui_story_31290401_130_dialog_content = "... ¿En serio?",
  ui_story_31290401_131_dialog_content = "Sí. No soy de los que se quedan atascados en el pasado y dejan de avanzar. Eso no es algo que haría una persona madura.",
  ui_story_31290401_132_dialog_content = "Si me preguntas, la mejor forma de honrar los deseos del viejo comandante es poner mi corazón y alma en mi trabajo.",
  ui_story_31290401_133_dialog_content = "Así que... ¿Es esa la razón por la que has estado trabajando hasta la muerte últimamente?",
  ui_story_31290401_134_dialog_content = "Claro, también es por el bien de hacer crecer a los Mercenarios de Llama Blanca y darles una vida mejor.",
  ui_story_31290401_135_dialog_content = "Pero... Pero tu capitán me dijo, hace un momento, que todavía estabas de luto por la muerte del viejo comandante.",
  ui_story_31290401_136_dialog_content = "¿Él también...? ¿Es eso lo que piensan todos?",
  ui_story_31290401_137_dialog_content = "Me ha dicho que te han instado a que te tomes un descanso y que descanses, pero que no les haces caso y sigues trabajando sin parar.",
  ui_story_31290401_138_dialog_content = "Además, tu salud empieza a preocuparles también.",
  ui_story_31290401_139_dialog_content = "¿Mi salud? ¿Se refieren a... la tos?",
  ui_story_31290401_140_dialog_content = "Últimamente he controlado mis hábitos alimenticios, pero toda esta comida seca ha sido muy dura para mi garganta.",
  ui_story_31290401_141_dialog_content = "En cuanto a lo de trabajar sin parar, les dije perfectamente que...",
  ui_story_31290401_142_dialog_content = "... Ahora entiendo.",
  ui_story_31290401_143_dialog_content = "Parece que tenemos algunos problemas de comunicación.",
  ui_story_31290401_144_dialog_content = "He estado tan ocupado con todas estas tareas, que no he hablado con ellos de nada más que de negocios últimamente...",
  ui_story_31290401_145_dialog_content = "Hace años que no tengo una charla sincera con ninguno de ellos.",
  ui_story_31290401_146_dialog_content = "Para que un líder cometa este tipo de error...",
  ui_story_31290401_147_dialog_content = "Parece que el viejo comandante tenía una última cosa que enseñarme, después de todo.",
  ui_story_31290401_148_dialog_content = "Mis interacciones con mis hombres han sido deficientes, por así decir.",
  ui_story_31290401_149_dialog_content = "Necesito tomarme el tiempo para tener una buena comunicación con ellos... Y no mantenerme enterrado bajo mi trabajo.",
  ui_story_31290401_150_dialog_content = "Realmente se preocupan por ti, Luke.",
  ui_story_31290401_151_dialog_content = "Lo sé. Haré tiempo para hablar con todos ellos esta noche, lo prometo.",
  ui_story_31290401_152_dialog_content = "Después de todo, no son sólo mis compañeros de armas... También son mi familia.",
  ui_story_31290401_153_dialog_content = "¡Entonces parece que mi trabajo aquí acabó!",
  ui_story_31290401_154_dialog_content = "¡Hah! Gracias, PlayerName.",
  ui_story_31290401_155_dialog_content = "O mejor dicho, debería disculparme de nuevo. No parece que hayas podido divertirte mucho hoy aquí.",
  ui_story_31290401_156_dialog_content = "... Ten, acepta esta piedra de insecto pintada a mano como mis disculpas.",
  ui_story_31290401_157_dialog_content = "¿Una piedra de insecto pintada a mano?",
  ui_story_31290401_158_dialog_content = "¿Eh...? ¡Eh! Esta piedra...",
  ui_story_31290401_159_dialog_content = "¡Ah! ¡¡Es esta roca!!",
  ui_story_31290401_160_dialog_content = "¡¿No se parece a la que me golpeó antes en el trasero?!",
  ui_story_31290401_161_dialog_content = "¿Hmm? ¿Qué quieres decir? Suelo regalar mis piedras de insectos pintadas a mano a los demás cuando quiero mostrar mi gratitud.",
  ui_story_31290401_162_dialog_content = "¿Qué es eso de que te golpearon en el trasero?",
  ui_story_31290401_163_dialog_content = "Así es... Así es como tu capitán decidió llamar mi atención antes.",
  ui_story_31290401_164_dialog_content = "De todos modos, deberías prepararte para hablar con el capitán y los demás...",
  ui_story_31290401_165_dialog_content = "Oh, y por favor recuérdale... ¡¡Que tirar piedras nunca es una buena forma de pedir las cosas!!",
  ui_story_31290601_1_dialog_content = "Este es el <color=#FFB400>aleta lluviosa</color>, una bestia maravillosa en peligro de extinción.",
  ui_story_31290601_2_dialog_content = "Viven en bosques cálidos y húmedos.",
  ui_story_31290601_3_dialog_content = "Sus grandes alas les dan la capacidad de volar por el bosque como fantasmas.",
  ui_story_31290601_4_dialog_content = "Los dibujos de sus alas van y vienen, como la lluvia.",
  ui_story_31290601_5_dialog_content = "Cuando baten sus alas, los patrones ordinarios están conectados.",
  ui_story_31290601_6_dialog_content = "Y parecen arcoíris voladores.",
  ui_story_31290601_7_dialog_content = "Podríamos haber visto uno surcando el cielo...",
  ui_story_31290601_8_dialog_content = "Pero ahora está clavado en una caja.",
  ui_story_31290601_9_dialog_content = "<color=#e8d9bb>En lo profundo del bosque</color>",
  ui_story_31290601_10_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_31290601_11_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_31290601_12_dialog_content = "Gracias, Lucas.",
  ui_story_31290601_13_dialog_content = "No te preocupes, solo hago mi trabajo.",
  ui_story_31290601_14_dialog_content = "No puedo creer que haya atravesado los eclipses.",
  ui_story_31290601_15_dialog_content = "Estos cazadores furtivos son más brutales de lo que pensaba, ¡e incluso con los suyos!",
  ui_story_31290601_16_dialog_content = "Conocen el bosque como la palma de sus manos. Han tendido trampas donde están los Eclipsites.",
  ui_story_31290601_17_dialog_content = "Y dejaron atrás estos <color=#FFB400>signos de supervivencia</color>.",
  ui_story_31290601_18_dialog_content = "Mira las latas desechadas y la madera quemada... Todo por distracción.",
  ui_story_31290601_19_dialog_content = "No es de extrañar que el gremio no sepa qué hacer con ellos.",
  ui_story_31290601_20_dialog_content = "Si no fuera por tu habilidad psíquica, nos habría llevado mucho tiempo encontrarlos.",
  ui_story_31290601_21_dialog_content = "Pero igual los perdimos...",
  ui_story_31290601_22_dialog_content = "No, no podemos rendirnos. Déjame intentar de nuevo.",
  ui_story_31290601_23_dialog_content = "...",
  ui_story_31290601_24_dialog_content = "Simplemente hay demasiada información...",
  ui_story_31290601_25_dialog_content = "¿Podemos al menos decir en qué dirección están?",
  ui_story_31290601_26_dialog_content = "Los animales junto al lago parecen inquietos.",
  ui_story_31290601_27_dialog_content = "Dirijámonos.",
  ui_story_31290601_28_dialog_content = "Podría obtener más información si estamos más cerca.",
  ui_story_31290601_29_dialog_content = "(Hace unos tres días, Luke vino al Coloso a buscarme).",
  ui_story_31290601_30_dialog_content = "(Quería que lo ayudara a atrapar a los cazadores furtivos que estaban detrás de Rainy Flappers).",
  ui_story_31290601_31_dialog_content = "(Son un tipo de mariposa cuyas ventas fueron prohibidas por Umbraton Guild, pero todavía se comercializan algunas).",
  ui_story_31290601_32_dialog_content = "(Los vendedores fueron muy inteligentes. Bethel buscó en su lugar en varias ocasiones, pero no pudo encontrar nada).",
  ui_story_31290601_33_dialog_content = "(Así que le pidió a los Mercenarios de la Llama Blanca que atraparan a los cazadores furtivos y se ocuparan de este problema de una vez por todas).",
  ui_story_31290601_34_dialog_content = "Creo que vamos en la dirección correcta. Puedo sentir a los aurorianos.",
  ui_story_31290601_35_dialog_content = "No se mueven en absoluto.",
  ui_story_31290601_36_dialog_content = "Uno... Dos... Hay tres de ellos.",
  ui_story_31290601_37_dialog_content = "Ellos estan hablando.",
  ui_story_31290601_38_dialog_content = "\"¡Ponlos todos en esta bolsa! ¡Date prisa!\"",
  ui_story_31290601_39_dialog_content = "Pero no puedo distinguir el resto.",
  ui_story_31290601_40_dialog_content = "Creo que son pupas Rainy Flapper. Deben emerger pronto.",
  ui_story_31290601_41_dialog_content = "Tres de ellos... Justo como supuso Bethel.",
  ui_story_31290601_42_dialog_content = "Hay muchas personas involucradas en la venta, pero la caza furtiva la realizan solo unas pocas personas.",
  ui_story_31290601_43_dialog_content = "Acerquémonos despacio para no alertarlos.",
  ui_story_31290601_44_dialog_content = "El bosque es inusualmente caliente.",
  ui_story_31290601_45_dialog_content = "Estoy tan sudado que es casi como si acabara de salir del agua.",
  ui_story_31290601_46_dialog_content = "Ahora sé por qué te quitaste la capa.",
  ui_story_31290601_47_option_content = "Sin embargo, te ves bien.",
  ui_story_31290601_48_dialog_content = "Gracias por el cumplido.",
  ui_story_31290601_49_option_content = "No te he visto con esta ropa antes.",
  ui_story_31290601_50_dialog_content = "No soy tan pobre como para tener que usar lo mismo todos los días.",
  ui_story_31290601_51_dialog_content = "El calor me habría detenido si no hubiera cambiado.",
  ui_story_31290601_52_dialog_content = "Aurorians y Caelestites no soportan el calor.",
  ui_story_31290601_53_dialog_content = "Pero Rainy Flappers solo puede sobrevivir en esta condición.",
  ui_story_31290601_54_dialog_content = "Una vez que abandonan el medio ambiente, sus alas se secan inmediatamente y no podrán volar.",
  ui_story_31290601_55_dialog_content = "¿Eso significa que mueren tan pronto como salen del bosque?",
  ui_story_31290601_56_dialog_content = "Esa es la peor parte, porque no hay muchos para empezar.",
  ui_story_31290601_57_dialog_content = "Y un gran número de ellos mueren durante el transporte desde el bosque hasta Umbraton.",
  ui_story_31290601_58_dialog_content = "Pero la pérdida no es necesariamente algo malo para los cazadores furtivos.",
  ui_story_31290601_59_dialog_content = "Porque cuanto menos hay, más pueden venderse en el mercado negro.",
  ui_story_31290601_60_dialog_content = "Ni el gremio ni yo queremos que esto suceda.",
  ui_story_31290601_61_dialog_content = "Al igual que todas las otras bestias maravillosas, Rainy Flappers debe ser atendido.",
  ui_story_31290601_62_dialog_content = "Entiendo.",
  ui_story_31290601_63_dialog_content = "Gracias, PlayerName.",
  ui_story_31290601_64_dialog_content = "No sé cómo agradecerte tu comprensión y ayudante. YO...",
  ui_story_31290601_65_dialog_content = "¡Espera, se están escapando!",
  ui_story_31290601_66_dialog_content = "¡Ve!",
  ui_story_31290601_67_dialog_content = "Se separaron y cada uno tiene una bolsa.",
  ui_story_31290601_68_dialog_content = "Si quisieron decir lo que dijeron antes...",
  ui_story_31290601_69_dialog_content = "\"¡Ponlos todos en esta bolsa! ¡Date prisa!\"",
  ui_story_31290601_70_dialog_content = "¡Solo uno de los bolsos tiene los Flappers!",
  ui_story_31290601_71_dialog_content = "Pero solo somos dos. Cómo hacemos esto?",
  ui_story_31290601_72_dialog_content = "gloo...",
  ui_story_31290601_73_dialog_content = "¡Casi me caigo!",
  ui_story_31290601_74_dialog_content = "¿Por qué hay un charco aquí?",
  ui_story_31290601_75_dialog_content = "Esto no es un simple charco. Ellos son <color=#FFB400>glooey</color>, otra bestia maravillosa que parece limo.",
  ui_story_31290601_76_dialog_content = "Puedo ver escamas de mariposa en ellos. Los cazadores furtivos deben haberse ido por aquí.",
  ui_story_31290601_77_dialog_content = "¡Eso significa que están emergiendo!",
  ui_story_31290601_78_dialog_content = "Esta debe ser la dirección correcta.",
  ui_story_31290601_79_dialog_content = "¡No hay tiempo que perder!",
  ui_story_31290601_80_dialog_content = "(Los enemigos esta vez son más difíciles de tratar).",
  ui_story_31290601_81_dialog_content = "(Ellos saben dónde estamos sin importar cómo vayamos en círculos. Algo está pasando).",
  ui_story_31290601_82_dialog_content = "(Así que tuvimos que separarnos y no sabemos a quién van a atrapar).",
  ui_story_31290601_83_dialog_content = "(No saben que tengo los Flappers, ¿verdad?)",
  ui_story_31290601_84_option_content = "¡Alto!",
  ui_story_31290601_85_dialog_content = "¿¿¿Eh???",
  ui_story_31290601_86_dialog_content = "¿Cómo supiste que era yo? Quiero decir, es una posibilidad entre tres...",
  ui_story_31290601_87_dialog_content = "Hay tres de ustedes, pero dos de nosotros, por lo que es realmente dos en tres.",
  ui_story_31290601_88_dialog_content = "Las probabilidades están de nuestro lado.",
  ui_story_31290601_89_dialog_content = "Las escamas siguen cayendo de tu bolso, lo que significa que debes tener los Flappers.",
  ui_story_31290601_90_dialog_content = "Dos en tres significa que solo hay uno de ustedes.",
  ui_story_31290601_91_dialog_content = "Y te ves terriblemente frágil. ¡Te voy a romper todos los huesos!",
  ui_story_31290601_92_dialog_content = "¿No me escuchaste? Dije que somos dos.",
  ui_story_31290601_93_dialog_content = "¿Qué?",
  ui_story_31290601_94_dialog_content = "Déjamelo a mí.",
  ui_story_31290601_95_dialog_content = "¡Insectos! ¡Insectos!",
  ui_story_31290601_96_dialog_content = "¡No les tengo miedo! no soy afra...",
  ui_story_31290601_97_dialog_content = "Silencio.",
  ui_story_31290601_98_dialog_content = "Que hermosa vista",
  ui_story_31290601_99_dialog_content = "(Luke solo dejó salir los Flappers en la bolsa).",
  ui_story_31290601_100_dialog_content = "(Pero todas las mariposas del bosque están bailando con ellos).",
  ui_story_31290601_101_dialog_content = "Se ven mucho mejor cuando están volando por el aire.",
  ui_story_31290601_102_dialog_content = "En seguida.",
  ui_story_31290601_103_dialog_content = "Los cazadores furtivos los meten en la bolsa y luego meten cada uno en una caja para preservar su belleza.",
  ui_story_31290601_104_dialog_content = "Pero sus alas son tan sencillas y aburridas cuando no se mueven.",
  ui_story_31290601_105_dialog_content = "El arcoíris solo sale cuando baten sus alas.",
  ui_story_31290601_106_dialog_content = "¿Lo estás viendo?",
  ui_story_31290601_107_dialog_content = "¡Sí, lo soy!",
  ui_story_31290601_108_dialog_content = "¡Agh, agh!",
  ui_story_31290601_109_dialog_content = "Creo que tiraste de las cuerdas demasiado fuerte.",
  ui_story_31290601_110_dialog_content = "Ahora sabe cómo deben sentirse los Flappers.",
  ui_story_31290601_111_dialog_content = "¿Qué tal los otros dos?",
  ui_story_31290601_112_dialog_content = "Deben haber huido después de enterarse de que atrapamos a uno de ellos.",
  ui_story_31290601_113_dialog_content = "Pero no creo que lo dejen, porque el dinero es demasiado bueno.",
  ui_story_31290601_114_dialog_content = "Una vez que abres algo, el resto se vuelve mucho más fácil.",
  ui_story_31290601_115_dialog_content = "No olvides que Bethel tiene a toda la banda de Istvan detrás de ella.",
  ui_story_31290601_116_dialog_content = "Mmm... así es.",
  ui_story_31290601_117_dialog_content = "Es realmente bello.",
  ui_story_31290601_118_dialog_content = "Pero...",
  ui_story_31290601_119_dialog_content = "...¿Pero?",
  ui_story_31290601_120_dialog_content = "Pero es probablemente una oportunidad única en la vida.",
  ui_story_31290601_121_dialog_content = "No te preocupes, navegante. Hay otras formas de alabar y recordar su belleza.",
  ui_story_31290601_122_dialog_content = "<color=#e8d9bb> Unos días después...</color>",
  ui_story_31290601_123_dialog_content = "(Aquí es donde termina la historia.)",
  ui_story_31290601_124_dialog_content = "(Después de obtener pruebas concretas, Bethel envió a su gente a arrestar a los vendedores).",
  ui_story_31290601_125_dialog_content = "(Los cazadores furtivos que escaparon también fueron capturados).",
  ui_story_31290601_126_dialog_content = "(Estaban locos de miedo cuando vieron dos pulpos en su casa).",
  ui_story_31290601_127_dialog_content = "¿Quién eres?",
  ui_story_31290601_128_dialog_content = "Ahí tienes. Terminemos con esto.",
  ui_story_31290601_129_dialog_content = "¿Por qué hiciste todo tan pegajoso?",
  ui_story_31290601_130_dialog_content = "¿Hice?",
  ui_story_31290601_131_dialog_content = "Mira quien habla.",
  ui_story_31290601_132_dialog_content = "(Luke no se detuvo e inmediatamente comenzó otro trabajo después de terminar este).",
  ui_story_31290601_133_dialog_content = "(Ni siquiera pudimos despedirnos correctamente).",
  ui_story_31290601_134_dialog_content = "(Pero recibí una pintura de él. Él mismo la pintó).",
  ui_story_31290601_135_dialog_content = "(Es una pintura de lo que sucedió ese día en el bosque, con Rainy Flappers bailando por el bosque)."
}
return config
